import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContactService } from '@shared/../../core/services/contact.service';

@Component({
  selector: 'app-contatti',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './contatti.component.html',
  styleUrl: './contatti.component.scss',
})
export class ContattiComponent {
  form = {
    nome: '',
    email: '',
    oggetto: '',
    messaggio: '',
  };

  formStatus = signal<any>(null);
  isLoading = signal(false);

  constructor(private contactService: ContactService) {}

  onSubmit() {
    if (this.form.nome && this.form.email && this.form.messaggio && this.form.oggetto) {
      this.isLoading.set(true);

      this.contactService.sendMessage(this.form).subscribe({
        next: (response) => {
          this.isLoading.set(false);
          this.formStatus.set({
            success: true,
            message: response.message || 'Messaggio inviato con successo!',
          });
          this.form = { nome: '', email: '', oggetto: '', messaggio: '' };
          setTimeout(() => this.formStatus.set(null), 5000);
        },
        error: (error) => {
          this.isLoading.set(false);
          this.formStatus.set({
            success: false,
            message: 'Errore nell\'invio del messaggio. Riprova più tardi.',
          });
          setTimeout(() => this.formStatus.set(null), 5000);
        },
      });
    }
  }
}
